window.DOSIK=window.DOSIK||{};DOSIK["yc_learning"]={"1":[{"t":"tree","title":"학습의 조건","root":"학습","branches":[["경험","학습은 경험을 통하여 이루어진다"],["외현적 수행","외현적 수행이 없어도 학습은 이루어진다 · 수행(performance)이 없어도 학습은 일어날 수 있다"],["행동 변화 시점","행동 변화는 학습 경험 후에 즉시 일어나지 않아도 된다"],["태도","태도의 변화는 학습의 영역에 포함된다"]]},{"t":"vs","title":"학습으로 보는 변화와 보지 않는 변화","cols":[{"name":"학습의 영역","items":["경험을 통한 변화","태도의 변화"]},{"name":"학습이 아닌 변화","items":["약물에 의한 일시적 행동변화","성숙에 의한 변화","약물에 의한 일시적 신체 변화는 학습의 범주에 포함되지 않는다"]}]},{"t":"tree","title":"의식의 관점","root":"다윈(C. Darwin)의 진화론과 미국의 실용주의에 영향을 받았다","branches":[["경험과 의식","의식의 흐름도 경험이 변화하면 함께 변화한다"],["전체적 과정","의식은 변별적인 정보의 조각이 아닌 전체적이고 연속적인 과정이다"],["환경과의 관계","행동과 의식은 환경과의 관계에서 생성되고 소멸하는 과정이다"]]}],"2":[{"t":"tree","title":"고전적 조건형성 사례","root":"고전적 조건형성","branches":[["편견","범죄 뉴스에서 특정 국가의 사람을 보면 그 국가 국민에 대한 편견이 형성된다"],["공포","아이가 토끼 옆에 있을 때 갑자기 큰 소리에 노출되면, 토끼에 대한 공포가 형성된다"],["긍정적 이미지","멋진 아이돌 가수가 특정 제품을 광고하면, 그 제품에 대한 긍정적 이미지가 형성된다"],["혐오","A는 열 살 때 오이를 먹고 몇 시간 뒤 독감에 걸렸다. 그 후 A는 오이를 싫어하게 되었다"]]}],"3":[{"t":"tree","title":"시행착오설","root":"손다이크의 시행착오설","branches":[["점진적 학습","학습은 통찰적이라기보다 점진적이다"],["반응의 방향","학습된 반응은 이미 형성된 방향으로 일어나기 쉽다"],["연합","자극과 반응 간 연합은 연습만으로도 강화된다"]]},{"t":"cause","title":"효과의 법칙","causes":["반응 다음에 만족스러운 사상태 · (satisfying state of affairs)가 따라온다"],"result":"자극과의 연결 강도가 높아진다","effects":[]}],"4":[{"t":"flow","title":"추동감소이론","steps":["유기체는 욕구가 생길 때 유발되는 학습되지 않은 행동을 가지고 태어난다","유기체가 생리적으로 결핍되면 추동 상태를 초래한다","각 추동은 특정 자극과 연합된다"]},{"t":"flow","title":"각성이론","steps":["반응은 활동을 필요로 한다","활동은 피로를 유발한다","피로는 부적 추동 상태이기 때문에 피로 상태에서는 반응하지 않는 것이 강화적인 속성을 갖는다"]}],"5":[{"t":"tree","title":"회피 학습 사례","root":"개가 장벽을 뛰어넘는 학습","branches":[["조건 자극","불빛이 꺼지는 것은 고통에 대한 조건 자극이 된다"],["부적 강화","개가 장벽을 뛰어넘는 것은 부적 강화력을 가진다"],["두 종류의 학습","고전적 조건화와 조작적 조건화라는 두 종류의 학습 경험이 관여한다"],["해결학습","개가 장벽을 뛰어넘는 것은 공포를 종결시키는 활동을 학습한 것으로 해결학습(solution learning)에 해당된다"]]},{"t":"def","term":"미신행동","text":"손톱을 깎고 시험을 본 날 성적이 좋았다면 시험을 볼 때마다 손톱을 깎는다"},{"t":"table","title":"강화계획","head":["계획","특징"],"rows":[["변동비율강화계획","비교적 꾸준한 수행이 나타나며 고정비율강화계획보다 소거에 대한 저항이 크다"],["고정비율강화계획","강화 후 휴지가 나타난다"],["고정간격강화계획","강화 후 휴지가 나타난다"],["변동간격강화계획","일정 시간을 기준으로 강화가 주어지나 그 시간 간격이 평균시간을 전후 로 불규칙하게 변한다"]]}],"6":[{"t":"tree","title":"처벌의 원칙","root":"효과적인 처벌","branches":[["사전 경고","처벌 전 사전 경고를 하는 것이 효과적이다"],["시간 간격","행동과 처벌 간 시간 간격이 길수록 처벌의 효과는 떨어진다"],["구체적 제시","처벌 받는 행동은 분명하고 구체적인 용어로 제시되어야 한다"],["이유 설명","처벌 받는 행동이 받아들여질 수 없는 이유에 대해 설명해 주어야 한다"],["일관성","처벌은 일관성이 있어야 한다"],["대체 행동","처벌받는 행동을 대신할 바람직한 행동에 대한 학습 기회를 제공해야 한다"]]}],"7":[{"t":"tree","title":"잠재학습","root":"톨만의 기호형태설","branches":[["강화","강화(reinforcement)는 학습에 필수적이지 않다"],["수행","학습된 것이 행동으로 드러나지 않을 수 있다"],["보상","보상의 유무는 학습된 결과가 행동으로 나타나는 것에 영향을 미친다"],["인지도","학습의 결과는 인지도(cognitive map)로 만들어진다"]]}],"8":[{"t":"tree","title":"통찰학습의 특징","root":"통찰학습","branches":[["근거","‘전체는 부분의 합 이상’ 이라는 게슈탈트 심리학에 근거한다"],["과정","문제해결에서 정신적 숙고의 과정을 거치며 미해결에서 해결 상태로의 이행이 갑작스럽다"],["유지","통찰로 얻은 해결책은 상당한 시간 동안 유지된다"],["수행","통찰로 얻은 해결책에 기초한 수행은 대개 부드럽고 오류가 없다"],["적용","통찰로 얻은 원리는 구조적으로 유사한 문제에 쉽게 적용할 수 있다 · 학습자는 통찰을 통한 문제해결의 원리를 구조적으로 유사한 문제에 쉽게 적용할 수 있다"]]}],"9":[{"t":"def","term":"관찰학습","text":"모델의 행동을 관찰함으로써 학습하는 것이다","ex":["관찰된 정보를 심상적, 언어적 표상체계로 부호화한다"]},{"t":"tree","title":"관찰학습의 특징","root":"반두라의 사회인지학습이론","branches":[["동물","인간 외의 동물들도 관찰을 통해 학습할 수 있다"],["모델의 매력","인간은 모델이 매력적이고 유명한 사람일 때 더 잘 배우는 경향이 있다"],["비숙련 모델","비숙련 모델(unskilled model)은 관찰자에게 모델의 성공뿐만 아니라 실패로부터도 배우게 한다"]]}],"11":[{"t":"table","title":"피아제의 인지 개념","head":["개념","내용"],"rows":[["평형화(equilibrium)","연속적인 변화를 겪으면서 일정한 인지구조를 유지하는 과정"],["동화(assimilation)","새로운 환경자극을 자신의 인지 도식에 적용시켜 불일치를 해결하는 것"],["내면화(interiorization)","물리적 환경에 대한 의존성이 점차 감소하고 인지구조의 활용이 증가하는 것"]]},{"t":"def","term":"전이의 핵심요인","text":"한 형태의 추론에서 다른 형태로의 추론으로 전이하는 핵심요인은 물리적 환경, 성숙, 사회적 영향, 평형이다"},{"t":"tree","title":"사회문화적 관점","root":"사회와 문화적 맥락에서의 학습에 초점을 둔다","branches":[["문화적 도구","언어나 상징과 같은 문화적 도구의 중요성을 강조한다"],["근접발달영역","근접발달영역(ZPD)에서 학습이 이루어진다"],["상호작용","지식은 혼자 발견하기보다 타인과의 상호작용을 통해 전수된다"]]}],"12":[{"t":"flow","title":"기억의 처리 과정","steps":["감각기억은 선택적 지각에 의해 단기기억으로 처리된다","새로운 정보는 단기기억을 거친 다음에 장기기억으로 이동한다"]},{"t":"table","title":"기억체계의 요소","head":["요소","내용"],"rows":[["앳킨슨-쉬프린(Atkinson-Shiffrin)의 기억모형","감각등록기, 단기기억, 그리고 장기기억 간의 체계를 설명한다"],["감각등록기(sensory register)","외부로부터의 정보를 수용하며, 매우 짧은 기간 유지되는 기억체계의 요소이다"],["작업기억(working memory)","정보를 조직하고 다른 정보들과 관련짓는 기억체계의 요소이다"],["절차기억(procedural memory)","자전거 타기, 수영하기, 타이핑하기 등이 있다"]]},{"t":"tree","title":"이중부호화","root":"정보가 장기기억에 저장되는 방식에 대한 이론이다","branches":[["그림","단어보다 그림을 더 잘 기억한다"],["부호","정보는 시각적 부호와 언어적 부호로 입력된다"],["시청각 교재","시청각 교재가 학습효과를 촉진한다"]]}],"13":[{"t":"vs","title":"망각 이론","cols":[{"name":"쇠퇴(decay)이론","items":["기억 흔적이 점차 사라지기 때문에 망각이 일어난다"]},{"name":"간섭(interference)이론","items":["정보가 다른 정보와 섞이거나 다른 정보에 의해 대체되기 때문에 망각이 일어난다"]}]},{"t":"vs","title":"역행간섭과 순행간섭","cols":[{"name":"역행간섭(역행제지)","items":["나중에 학습한 정보가 앞서 학습한 정보의 회상을 방해하는 것","알파벳 ‘d’를 배우게 되면서, 앞서 배웠던 ‘b’를 혼동하는 것"]},{"name":"순행간섭","items":["개명한 친구의 새 이름이 기억나지 않고 예전 이름만 떠오르는 것"]}]},{"t":"tree","title":"기억과 전략","root":"기억","branches":[["메타인지 전략","계획하기, 평가하기, 점검하기 등이 있다"],["기억의 구분","기억은 재인 기억과 회상 기억으로 나눌 수 있다"],["감각등록기","감각등록기(sensory register)는 매우 짧은 시간동안 많은 정보를 저장한다"]]}],"14":[{"t":"table","title":"뇌의 구조와 물질","head":["대상","기능"],"rows":[["도파민","정적 강화를 받을 때 분비되는 신경전달 물질이며 강화중추와 관련 있는 호르몬이다"],["편도체","어떤 사건이나 정보를 기억할 때 그 기억에 감정을 결합시키는 역할을 하며 정서와 공격성의 통제를 담당한다"],["베르니케 영역","언어의 의미를 이해하는 데 중요한 기능을 한다"],["거울뉴런(mirror neuron)","타인의 행동을 마치 자신의 행동을 보는 것처럼 느끼게 하는 뉴런"]]},{"t":"tree","title":"뇌의 발달과 변화","root":"뇌","branches":[["신경가소성(neuroplasticity)","뇌가 신경연결을 재조직하거나 수정하는 능력 · 뇌가 경험한 결과들을 재조직하거나 수정하는 능력"],["국소화(localization)","출생 후 2∼3년에 걸쳐 이루어진다"],["신경생성(neurogenesis)","성인기 이후에도 계속된다"],["전두엽","발달은 유아기 때 빠르며, 사춘기 이후에도 계속된다"],["수초화","뉴런의 두께가 두꺼워지는 과정이며, 수초화가 된 뉴런은 정보를 더 빨리 전달한다"]]}],"15":[{"t":"vs","title":"결핍 욕구와 성장 욕구","cols":[{"name":"결핍 욕구","items":["생존에 필수적인 욕구","만족되면 다음 단계로 넘어갈 수 있다","소속감과 애정에 대한 욕구","자아존중에 대한 욕구","생리적인 욕구는 평형을 유지하려는 욕구이다"]},{"name":"성장 욕구","items":["성장을 추구하는 욕구","자아실현에 대한 욕구","자아실현 욕구는 모든 인간에게 내재되어 있다","자아실현 욕구는 완전히 만족되지 않는다"]}]},{"t":"def","term":"욕구위계","text":"하위 단계의 욕구가 충족된 다음에 상위 단계 욕구가 나타난다"},{"t":"def","term":"내적 조절","text":"통합된 조절(integrated regulation)보다 · 내적 조절(intrinsic regulation)의 자율성 정도가 더 높다"}],"16":[{"t":"vs","title":"수행목표와 숙달목표","cols":[{"name":"수행목표","items":["남의 눈에 유능하게 보이는 것에 해당한다","외적으로 동기화되어 있어 외적인 강화나 처벌에 민감하다","시험이나 과제 수행 시 몹시 긴장하는 일이 많다","오류를 실패와 무능으로 여긴다","실패하면 쉽게 좌절한다"]},{"name":"숙달목표","items":["스스로 더 유능한 사람이 되려는 것에 해당한다","숙달목표 지향적인 사람은 학습과 행동을 스스로 조절한다","실패를 해도 수행에 만족할 수 있다"]}]},{"t":"table","title":"귀인 요인","head":["요인","성격"],"rows":[["과제 난이도","외적, 통제 불가능 요인"],["행운이나 우연","외적, 불안정 요인"]]},{"t":"table","title":"귀인과 정서","head":["귀인","정서"],"rows":[["실패가 외적인 원인이라고 생각","화가 나고 분하다"],["실패가 자신의 능력의 부족이라고 생각","죄책감이나 수치심을 느낀다"]]}],"17":[{"t":"def","term":"몰입","text":"활동에 완벽하게 몰두하는 상태를 말한다","ex":["과제 도전정도와 학습자 기술수준의 균형이 맞을 때 나타난다"]},{"t":"table","title":"도전정도와 기술수준","head":["상황","결과"],"rows":[["도전정도가 기술수준보다 너무 높음","불안해진다"],["기술수준이 도전정도보다 너무 높음","지루해진다"]]}],"18":[{"t":"table","title":"학습전이 이론","head":["이론","내용"],"rows":[["형식도야설(formal discipline)","연습과 훈련을 통해 주의력, 기억력, 판단력을 향상시킬 수 있다"],["동일요소설(identical elements)","학습과제 사이에 유사성의 정도가 높을수록 전이가 많이 일어 난다"],["일반화설(generalization)","선행학습에서 획득한 원리나 법칙을 후속학습에 활용할 수 있다"],["형태이조설(transposition)","선행과 후속학습 간의 관계적 통찰이 전이를 일으킨다"]]},{"t":"def","term":"근접 전이(near transfer)","text":"학습활동시의 맥락과 전이 상황의 맥락이 유사할 때 일어난다"}]};
